public TableId journalTable()
{
    // TODO we don't really have a header table with METRebateScanSupplierTable
    return tableNum(METRebateScanSupplierTable);
}

public FieldId transTableRecIdFieldId()
{
    return fieldNum(METRebateScanSupplierTable, RecId);
}

protected void addTransRange()
{
    TAMRebateTransactionType rebateTransactionType = this.metParmRebateTransactionType();

    // only select records with a vendor account
    //query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, VendAccount)).value(SysQuery::valueNotEmptyString());
    query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, CustAccount)).value(SysQuery::valueEmptyString());

    // Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
    VendAccount vendAccount = rebateTable.TAMRebateDeal().METVendAccount;

    if (vendAccount)
    {
        // Is there a way to find out if attribute is used?
        SysQuery::findOrCreateRange(query.dataSourceTable(this.journalTable()), this.accountJourTableFieldId()).value(vendAccount);
    }

    if (rebateTransactionType == TAMRebateTransactionType::Provision)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, ProvisionPosted)).value(queryValue(NoYes::No));

    }
    else if (rebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, RebatePosted)).value(queryValue(NoYes::No));
    }
}

public Query buildBaseQuery()
{
    query = new Query();

    //QueryBuildDataSource qbds = query.addDataSource(this.journalTable());
    QueryBuildDataSource qbds = query.addDataSource(this.transTable());

    QueryBuildRange qbr = qbds.addRange(this.accountJourTableFieldId());
    qbr.status(RangeStatus::Locked);

    /*qbds = qbds.addDataSource(this.transTable());
    qbds.relations(true);
    qbds.fetchMode(QueryFetchMode::One2One);*/

    qbr = qbds.addRange(this.itemFieldId());
    qbr.status(RangeStatus::Locked);

    qbr = qbds.addRange(this.dateFieldId());
    qbr.status(RangeStatus::Locked);

    return query;
}
